        "agent-architecture",
        "intent-control-separation",
        "closed-loop-intent-prediction",
        "human-video-learning",
        "object-flow",
        "palm-pose-reference",
        "goal-conditioned-policy",
        "task-agnostic-controller",
        "cross-embodiment",
        "reinforcement-learning",
        "ppo",
