      "id": "AM.MAN.DEX.POLICY.LEARNING.10",
      "slug": "dexter",
      "short_name": "DextER",
      "title": "DextER: Language-driven Dexterous Grasp Generation with Embodied Reasoning",
      "authors": "Junha Lee, Eunha Park, Minsu Cho",
      "year": 2026,
      "venue": "CVPR 2026 / arXiv v2",
      "kind": "model",
      "category": "AM.MAN.DEX.POLICY.LEARNING",
